import { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { ArrowRight, ChevronLeft, ChevronRight } from 'lucide-react'
import { siteConfig } from '../config/site'

const slides = siteConfig.hero.slides

export default function HeroCarousel() {
  const [current, setCurrent] = useState(0)
  const [direction, setDirection] = useState(1)

  const goTo = useCallback(
    (index: number) => {
      setDirection(index > current ? 1 : -1)
      setCurrent(index)
    },
    [current]
  )

  const next = useCallback(() => {
    setDirection(1)
    setCurrent((prev) => (prev + 1) % slides.length)
  }, [])

  const prev = useCallback(() => {
    setDirection(-1)
    setCurrent((prev) => (prev - 1 + slides.length) % slides.length)
  }, [])

  useEffect(() => {
    const timer = setInterval(next, 6000)
    return () => clearInterval(timer)
  }, [next])

  const variants = {
    enter: (dir: number) => ({
      x: dir > 0 ? 80 : -80,
      opacity: 0,
    }),
    center: {
      x: 0,
      opacity: 1,
    },
    exit: (dir: number) => ({
      x: dir > 0 ? -80 : 80,
      opacity: 0,
    }),
  }

  return (
    <section className="relative min-h-[90vh] lg:min-h-screen flex items-center justify-center overflow-hidden bg-bg-primary pt-20">
      {/* Background gradient */}
      <div className="absolute inset-0 bg-gradient-to-br from-bg-primary via-bg-secondary to-bg-primary opacity-80" />
      <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-accent/5 rounded-full blur-3xl" />
      <div className="absolute bottom-1/4 right-1/4 w-80 h-80 bg-accent-warm/5 rounded-full blur-3xl" />

      <div className="relative z-10 max-w-7xl mx-auto px-6 lg:px-8 w-full py-16 lg:py-24">
        <div className="grid lg:grid-cols-2 gap-12 lg:gap-20 items-center">
          {/* Text Content */}
          <div className="order-2 lg:order-1">
            <AnimatePresence mode="wait" custom={direction}>
              <motion.div
                key={current}
                custom={direction}
                variants={variants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ duration: 0.5, ease: [0.32, 0.72, 0, 1] }}
              >
                <span className="inline-block text-xs font-semibold tracking-widest uppercase text-accent mb-4">
                  Featured
                </span>
                <h1 className="font-display text-4xl sm:text-5xl lg:text-6xl xl:text-7xl font-bold leading-[1.05] tracking-tight text-text-primary mb-6">
                  {slides[current].title}
                </h1>
                <p className="text-base lg:text-lg text-text-secondary leading-relaxed max-w-lg mb-8">
                  {slides[current].description}
                </p>
                <a
                  href={slides[current].cta.href}
                  className="inline-flex items-center gap-2 px-6 py-3 bg-text-primary text-bg-primary font-semibold text-sm rounded-full hover:bg-accent hover:text-white transition-all duration-300 group"
                >
                  {slides[current].cta.label}
                  <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                </a>
              </motion.div>
            </AnimatePresence>

            {/* Slide Indicators */}
            <div className="flex items-center gap-3 mt-12">
              {slides.map((_, i) => (
                <button
                  key={i}
                  onClick={() => goTo(i)}
                  className={`h-1 rounded-full transition-all duration-300 ${
                    i === current ? 'w-8 bg-accent' : 'w-4 bg-text-muted hover:bg-text-secondary'
                  }`}
                  aria-label={`Go to slide ${i + 1}`}
                />
              ))}
              <span className="ml-2 text-xs text-text-muted font-mono">
                {String(current + 1).padStart(2, '0')} / {String(slides.length).padStart(2, '0')}
              </span>
            </div>
          </div>

          {/* Visual Card */}
          <div className="order-1 lg:order-2 flex justify-center lg:justify-end">
            <AnimatePresence mode="wait" custom={direction}>
              <motion.div
                key={current}
                custom={direction}
                variants={variants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ duration: 0.5, ease: [0.32, 0.72, 0, 1] }}
                className="relative w-full max-w-md aspect-[4/5] rounded-2xl overflow-hidden bg-bg-secondary border border-border shadow-2xl"
              >
                <div className="absolute inset-0 bg-gradient-to-t from-bg-primary via-transparent to-transparent z-10" />
                <img
                  src={`https://images.unsplash.com/photo-${[
                    '1677442136019-21780ecad995',
                    '1485827404703-89b55fcc595e',
                    '1576091160399-112ba8d25d1d',
                    '1478737270239-2f02b77ac6d5',
                    '1551288049-bebda4e38f71',
                  ][current]}?w=600&h=750&fit=crop`}
                  alt={slides[current].title}
                  className="w-full h-full object-cover"
                />
                <div className="absolute bottom-0 left-0 right-0 p-6 z-20">
                  <span className="text-xs font-semibold tracking-wider uppercase text-accent mb-2 block">
                    {slides[current].cta.label}
                  </span>
                  <h3 className="font-display text-xl font-semibold text-text-primary">
                    {slides[current].title}
                  </h3>
                </div>
              </motion.div>
            </AnimatePresence>
          </div>
        </div>

        {/* Navigation Arrows */}
        <div className="hidden lg:flex items-center gap-3 absolute bottom-12 right-8">
          <button
            onClick={prev}
            className="w-12 h-12 rounded-full border border-border bg-bg-secondary/80 backdrop-blur flex items-center justify-center text-text-secondary hover:text-text-primary hover:border-text-secondary transition-all"
            aria-label="Previous slide"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
          <button
            onClick={next}
            className="w-12 h-12 rounded-full border border-border bg-bg-secondary/80 backdrop-blur flex items-center justify-center text-text-secondary hover:text-text-primary hover:border-text-secondary transition-all"
            aria-label="Next slide"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      </div>
    </section>
  )
}

